        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by incorrectly checking the pointer to the error (`pe`) instead of the actual error value (`err`). This led to a situation where the program could mistakenly ignore a valid socket error when handling a `POLLHUP` event, potentially allowing the application to proceed with an invalid connection state.

        Commit message:
        tcp: check socket error when connect gets POLLHUP

This fixes a bug in d56ddab49d3e3433fb5b6e13d63f13f9eda27b57
in which we check the socket error. We erroneously checked the
pointer to the error, not the error itself. This commit fixes that.  

        Patch:

 static int
 tcp_poll_events(cci__ep_t *ep)
 {
 	int ret = CCI_EAGAIN, i, count;
 	tcp_ep_t *tep = ep->priv;

 	if (!tep)
 		return CCI_ENODEV;

 	pthread_mutex_lock(&ep->lock);
 	if (ep->closing || tep->is_polling) {
 		pthread_mutex_unlock(&ep->lock);
 		CCI_EXIT;
 		return ret;
 	}

 	tep->is_polling++;
 	assert(tep->is_polling == 1);
 	pthread_mutex_unlock(&ep->lock);

 	/* check for incoming messages (POLLIN) _and_
 	 * connect completions (POLLOUT)
 	 */
 	ret = poll(tep->fds, tep->nfds, 0);
 	if (ret < 1) {
 		if (ret == -1) {
 			ret = errno;
 			debug(CCI_DB_EP, "%s: poll() returned %s",
 				__func__, strerror(ret));
 		} else {
 			ret = CCI_EAGAIN;
 		}
 		goto out;
 	}

 	count = ret;
 	debug(CCI_DB_EP, "%s: poll found %d events", __func__, count);

 	i = 0;
 	do {
 		uint32_t found = 0;
 		short revents = tep->fds[i].revents;
 		cci__conn_t *conn = tep->c[i];
 		tcp_conn_t *tconn = NULL;

 		if (revents) {
 			debug(CCI_DB_EP, "%s: revents 0x%x",
 				__func__, revents);
 		} else {
 			goto increment;
 		}

 		if (conn)
 			tconn = conn->priv;

 again:
 		if (revents & POLLHUP) {
 			tcp_conn_status_t old_status = tconn->status;
 			cci__evt_t *evt = NULL;
 			tcp_tx_t *tx = NULL;
 			int rc = 0;
 			socklen_t err = 0, *pe = &err, slen = sizeof(err);

 			rc = getsockopt(tconn->fd, SOL_SOCKET, SO_ERROR, (void*)pe, &slen);
-			if (old_status == TCP_CONN_ACTIVE1 && pe == 0 && revents != POLLHUP) {
+			if (old_status == TCP_CONN_ACTIVE1 && err == 0 && revents != POLLHUP) {
 				debug(CCI_DB_CONN, "%s: ignoring spurious POLLHUP for "
 					"for async connection completion - connection "
 					"is valid", __func__);
 				revents = revents & (~(POLLHUP));
 				goto again;
 			}

 			/* handle disconnect */
 			debug(CCI_DB_CONN, "%s: got POLLHUP on conn %p (%s) revents (0x%x) %s",
 				__func__, (void*)conn, tcp_conn_status_str(tconn->status),
 				revents, strerror(err));

 			pthread_mutex_lock(&ep->lock);
 			tcp_conn_set_closing_locked(ep, conn);
 			pthread_mutex_unlock(&ep->lock);

 			switch (old_status) {
 			case TCP_CONN_READY:
 				/* TODO drain queues */
 				break;
 			case TCP_CONN_ACTIVE1:
 			case TCP_CONN_ACTIVE2:
 				pthread_mutex_lock(&tconn->slock);
 				if (old_status == TCP_CONN_ACTIVE1) {
 					evt = TAILQ_FIRST(&tconn->queued);
 					TAILQ_REMOVE(&tconn->queued, evt, entry);
 				} else {
 					evt = TAILQ_FIRST(&tconn->pending);
 					TAILQ_REMOVE(&tconn->pending, evt, entry);
 				}
 				pthread_mutex_unlock(&tconn->slock);

 				evt->event.connect.status = CCI_ETIMEDOUT;
 				tx = container_of(evt, tcp_tx_t, evt);
 				tx->state = TCP_TX_COMPLETED;

 				pthread_mutex_lock(&ep->lock);
 				TAILQ_INSERT_TAIL(&ep->evts, evt, entry);
 				pthread_mutex_unlock(&ep->lock);
 				break;
 			case TCP_CONN_PASSIVE1:
 			case TCP_CONN_PASSIVE2:
 				/* handled in tcp_conn_set_closing_locked() */
 				break;
 			case TCP_CONN_CLOSING:
 				fprintf(stderr, "%s: got POLLHUP on conn %p (%s) "
 						"with status TCP_CONN_CLOSING\n",
 						__func__, (void*)conn, conn->uri);
 				break;
 			default:
 				debug(CCI_DB_CONN, "%s: connection status was %s",
 					__func__, tcp_conn_status_str(tconn->status));
 			}

 			goto out;
 		}
 		if (revents & POLLIN) {
 			found++;
 			if (i == 0) {
 				/* handle accept */
 				tcp_handle_listen_socket(ep);
 			} else {
 				/* process recv */
 				if (conn)
 					tcp_handle_recv(ep, conn);
 				else
 					debug(CCI_DB_WARN, "%s: POLLIN event on "
 						"fds[%d] but no conn in tep->c",
 						__func__, i);
 			}
 		}
 		if (revents & POLLOUT) {
 			if (tconn->status == TCP_CONN_ACTIVE1) {
 				/*  send CONN_REQUEST on new connection */
 				debug(CCI_DB_CONN, "%s: connect() completed", __func__);
 				tconn->status = TCP_CONN_ACTIVE2;
 				tep->fds[i].events = POLLIN | POLLOUT;
 			}
 			pthread_mutex_lock(&ep->lock);
 			tcp_progress_conn_sends(conn, 1);
 			pthread_mutex_unlock(&ep->lock);
 			found++;
 		}
 		if (revents & POLLERR) {
 			/* handle error */
 			debug(CCI_DB_CONN, "%s: got POLLERR on conn %p",
 				__func__, (void*)conn);
 			found++;
 		}
 		if (!found && revents)
 			debug(CCI_DB_WARN, "%s: unhandled revents %u",
 				__func__, revents);
 		if (found)
 			count--;
 increment:
 		i++;

 		if (count == (int)tep->nfds)
 			break; /* because OSX returns the wrong count from poll */
 	} while (count);

 out:
 	pthread_mutex_lock(&ep->lock);
 	/* TODO process queued changes to tep->fds, tep->c */
 	tep->is_polling = 0;
 	pthread_mutex_unlock(&ep->lock);

 	return ret;
 }



